CHAINS=[{'chain': '600082-卖房已收款交付，什么还没完成', 'source': '1225590832', 'pages': [1], 'subject': '卖房已收款交付，什么还没完成', 'changed': '10月1日披露55006.89万元交易已签约、全款收到并实际交付；从拟议出售推进到真实履约。', 'open': '房产过户登记后续办理，实际收款日未由本件精确给定；不把截至披露日当10月1日当天收款，年度财务影响及处罚警示撤销另核。', 'supporting': []}, {'chain': '600082-扭亏与经营现金，怎样解释', 'source': '1225612213', 'pages': [1, 3], 'subject': '扭亏与经营现金，怎样解释', 'changed': '三季度归母与扣非均54430671.74元，前三季经营现金558045315.92元；公司解释房产销售及融资成本改善。', 'open': '房产为开发项目可售库存，不能套用所有出售款均非经营现金；扣非盈利不代表无集中关联交易依赖，也不替代处罚门槛和年度审计。', 'supporting': []}, {'chain': '600084-盈利后，现金和年度门槛过了吗', 'source': '1225636186', 'pages': [1], 'subject': '盈利后，现金和年度门槛过了吗', 'changed': '前三季归母9623526.53元、扣非4693369.72元，经营现金仍负18611886.65元；第三季单季现金累计差额另算为正。', 'open': '半年预增与正式半年及三季报分别更新；前三季普通营收不当全年扣除后营收，未审计期报不当正式摘帽。', 'supporting': []}, {'chain': '600084-酒类销售增长，和报表收入是否同口径', 'source': '1225636178', 'pages': [1], 'subject': '酒类销售增长，和报表收入是否同口径', 'changed': '1至9月酒类产品销售13314.55万元，同比增长53.78%，经销商期末130家。', 'open': '酒类分产品销售口径不等于财报全部营业收入；半年地区分类单列新疆而9月表不再单列新疆，不能直接拼接单一区域增速。', 'supporting': []}, {'chain': '600107-450万股竞买成功，是否已经过户', 'source': '1225601565', 'pages': [1, 3], 'subject': '450万股竞买成功，是否已经过户', 'changed': '450万股三批网拍竞买成功，合计18459000元。', 'open': '法院成交裁定、缴款和变更过户仍待核；股东股份处置不是上市公司收款，不推控制权变更。', 'supporting': []}, {'chain': '600107-410万股流拍，是同一批成功股份吗', 'source': '1225636636', 'pages': [1], 'subject': '410万股流拍，是同一批成功股份吗', 'changed': '另一批410万股变卖截至10月25日无人出价，10月29日披露流拍。', 'open': '410万与450万主体批次、法院和程序分开，不把成功与流拍混成一项；后续司法措施未定。', 'supporting': []}, {'chain': '600107-单季转盈，是否已摆脱全年和内控约束', 'source': '1225642978', 'pages': [1, 2], 'subject': '单季转盈，是否已摆脱全年和内控约束', 'changed': '第三季归母1151723.68元、扣非253524.85元为正，前三季归母、扣非仍亏损，经营现金负93043574.24元。', 'open': '财务组合和内控两年否定分别核；月度风险提示不是新增独立催化，期报也不是新的独立内控审计。三季报资金占用费收益7314077.27元与旧回复两笔已付利息合计7752921.90元口径未解释，不强行认定相等。', 'supporting': []}, {'chain': '600119-一审胜诉以后，案件是否结束', 'source': '1225465715', 'pages': [1, 2], 'subject': '一审胜诉以后，案件是否结束', 'changed': '7月一审驳回原告诉求，8月收到原告上诉状；案件身份仍为（2025）沪7101民初1382号对应上诉。', 'open': '一审未生效不当终局胜诉；不同原案547号与重诉1382号分开，后续生效法律文书仍待核。', 'supporting': [{'source': '1225436857', 'pages': [1, 3, 4], 'state': '一审结果与上诉期说明，不当最终结案。'}]}, {'chain': '600119-冲回预计负债以后，利润与现金怎样', 'source': '1225640975', 'pages': [2, 3, 5], 'subject': '冲回预计负债以后，利润与现金怎样', 'changed': '三季报列21462899元案件预计负债冲回；三季度归母16871653.84元、扣非负4976491.62元，单季经营现金负44761253.08元。', 'open': '入账冲回不当现金回款，也不由此推定案件生效；累计归母转正不替代扣非、经营现金及年度条件。比较期采用同一控制合并调整后，不与调整前列混算。', 'supporting': []}, {'chain': '600119-四次挂牌，是否已经换成现金', 'source': '1225598978', 'pages': [1, 2], 'subject': '四次挂牌，是否已经换成现金', 'changed': '持有关勒铭全部15.7143%股权第四次挂牌10月8日期满，未征集到受让方，后续是否再挂牌未定。', 'open': '全部持有股权不是标的100%股权；未成交不当处置收益或回款，重复挂牌不当四次成功经验。', 'supporting': []}]
