def followup_view(inputs, prior):
    packet=inputs.get('thirteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('thirteenth period packet changed')
    if prior is None or prior['counts']['after']!=94 or packet['prior_digest']!=digest(prior):raise ValueError('thirteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('thirteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=25 or len(packet['sources'])!=25 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('thirteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('thirteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('thirteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('thirteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('thirteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('thirteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('thirteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('thirteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('thirteenth period quarter changed')
        if row['reported_quarter_yuan']is not None and D(row['reported_quarter_yuan'])!=nine-h:raise ValueError('thirteenth period reported quarter changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('thirteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('thirteenth period windows changed')
